INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,1,'🐛📝','我是一条小蚯蚓，住在泥土下面的小小房间里。今天是我写日记的第一天！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,2,'🌧️🕳️','下雨了，我和小伙伴们钻出地面，在湿漉漉的草地上快乐地散步。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,3,'📚🕷️','我去找蜘蛛朋友玩，可是我不会像他那样倒挂着走路，真好玩呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,4,'🍎🍽️','今天的晚餐是烂苹果，妈妈说这可是蚯蚓界的美食呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,5,'🎒🏫','我不用背书包上学，因为老师教我们钻洞就好了，真是太轻松了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (74,6,'🌙💤','晚安，我亲爱的小日记本，明天还会有新的故事哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,1,'👦🍔','小男孩大口大口地吃东西，肚子里的小精灵们准备好了吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,2,'🚂🏠','肚子里面有一个热闹的火车站，好多小精灵正等着运送食物呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,3,'🏃‍♂️📦','小精灵们把食物装上火车，运送到身体的各个地方，工作得好辛苦呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,4,'🍦😵','糟糕！一下子吃了太多冰激凌，小精灵们冻得直哆嗦，火车都开不动了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,5,'🤢🌩️','肚子里的火车站乱成一团，小男孩的肚子好疼好疼呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (75,6,'🥣😊','喝了暖暖的热汤，小精灵们又开心地工作起来啦！以后吃东西要慢慢嚼哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,1,'😀🍬','迪克和哈克是两个小细菌，他们住在小朋友的牙齿里面。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,2,'🏗️🏠','他们在牙齿上建房子，还挖了一个好大的游泳池，生活真舒服呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,3,'🍰🎉','小朋友吃了好多糖果蛋糕，细菌们可高兴了，开起了热闹的派对！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,4,'⛏️🏰','细菌们越挖越深，在牙齿上建起了一座大城堡，牙齿开始疼起来了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,5,'🪥🌊','牙刷巨人来啦！大水冲走了细菌的房子，细菌们吓得四处逃跑！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (76,6,'😁✨','小朋友每天认真刷牙，细菌再也不敢来建房子了，牙齿白白亮亮的真好看！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,1,'👦🌤️','小男孩看着窗外的风，问妈妈：风到哪里去了呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,2,'🌊🍃','风吹过大海，浪花翻滚起来，大海变得好开心呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,3,'🌸🌧️','风把云朵推到山那边，云朵变成雨落下来，花朵喝饱了水。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,4,'🍂🌳','风摇着树叶跳舞，树叶飘落到地上，变成大树的养分。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,5,'🌅🏔️','风跑到太阳身边，帮太阳把温暖的空气送到每个角落。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (77,6,'🌍💫','原来风没有消失，它只是换了个地方，继续让世界变得更美好呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,1,'💩🐭','小鼹鼠刚从洞里钻出来，头上就掉下来一坨嗯嗯！好臭好臭！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,2,'🔍🕊️','小鼹鼠气呼呼地去问鸽子：是不是你嗯嗯在我头上的？鸽子说不是我！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,3,'🐴❌','小鼹鼠又去问马先生，马的嗯嗯又大又多，和头上的完全不一样！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,4,'🐑🐷','问了山羊和猪，他们的嗯嗯形状都不一样，到底是谁的呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,5,'🐕😤','终于找到啦！是大狗的嗯嗯！小鼹鼠很生气，他也爬到大狗头上嗯嗯了一下！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (78,6,'😄🎉','虽然找了好久，但小鼹鼠终于弄明白了，每种动物的嗯嗯都不一样呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,1,'🏊‍♂️📊','小威是一个小小的精子，他住在布朗先生的身体里，数学不太好但游泳特别棒！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,2,'🏆💪','游泳大赛马上就要开始了，小威每天都在刻苦练习，他一定要拿冠军！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,3,'🗺️🏁','比赛路线好长好长啊，要游过好多地方才能到达终点。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,4,'🏊‍♂️💨','出发了！几百亿个选手一起游，小威拼命地往前冲！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,5,'🌟🥇','小威第一个到达了终点！他遇到了美丽的小卵，变成了一颗小小的种子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (79,6,'👶🎉','小种子慢慢长大，变成了一个小宝贝！原来每个小朋友都是最棒的冠军呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,1,'👧🤱','小宝宝出生了，妈妈用乳房喂宝宝喝奶，宝宝喝得好香好香。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,2,'🍼💕','妈妈的奶水里有好多营养，让小宝宝一天天长大，变得越来越健康。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,3,'🧸👧','小女孩问妈妈：为什么妈妈的乳房比我大呢？妈妈温柔地解释给她听。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,4,'👶🌿','乳房是妈妈给宝贝最珍贵的礼物，用爱哺育着每一个小生命。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,5,'💐🤱','不管乳房是大是小，它们都充满了妈妈对宝宝的爱和温暖。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (80,6,'❤️🌈','我们的身体真奇妙，每个部分都有特别的作用，我们要好好爱护自己！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,1,'👦🩲','小明洗完澡，看着镜子里的自己，发现自己和妹妹不太一样呢。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,2,'👨‍👩‍👧‍👦❓','爸爸说：男孩子和女孩子有些地方不一样，这都很正常哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,3,'🚽🧼','我们要好好保护自己的身体，上厕所后要擦干净，每天都要洗小鸡鸡。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,4,'🛑🙅','如果有人要摸你的小鸡鸡，一定要大声说不行，然后告诉爸爸妈妈！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,5,'👶🏠','小鸡鸡还有很大的用处呢，等你长大了，它可以帮助你生小宝宝。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (81,6,'❤️😊','我们的身体是自己的宝贝，要好好爱护它，也要尊重别人的身体哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,1,'👶👀','小朋友们，你们知道身体里藏着好多秘密吗？让我们一起来发现吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,2,'🦴💪','骨头就像身体的支架，有了它我们才能站得直直的，跑得快快的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,3,'❤️🩸','心脏像个勤劳的小泵，不停地跳动，把血液送到身体的每个角落。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,4,'🫁💨','肺像两个小气球，吸气的时候变大，呼气的时候变小，真有趣！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,5,'🧠💭','大脑是身体的司令部，它让你会思考、会说话、会做各种各样的事情。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (82,6,'🌟😊','我们的身体真可爱，每一个部分都很重要，要好好吃饭锻炼身体哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,1,'🐒🏠','猴子的尾巴长长的，可以缠在树枝上荡秋千，真好玩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,2,'🐟➡️','鱼的尾巴像方向盘，左摆右摆就能在水里游来游去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,3,'🐄🪰','牛的尾巴像一把蝇拍，啪啪啪地把苍蝇赶走，再也不被咬了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,4,'🦘🦵','袋鼠的尾巴又粗又有力，坐在地上当凳子，跳起来还能保持平衡呢。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,5,'🦊❄️','狐狸的尾巴毛茸茸的，冬天裹在身上就像一条暖暖的围巾。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (83,6,'🦎✂️','壁虎的尾巴最神奇，被抓住了还能断掉再长出来一条新的！大自然真奇妙！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,1,'🏫🚌','弗瑞丝老师开着神奇校车来了！今天我们要去哪里探险呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,2,'🔬🔬','神奇校车变小了，变小了！我们钻进了小水滴里面！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,3,'☁️🌧️','我们跟着水滴飞上了天空，变成了一朵小云彩，风一吹就飘来飘去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,4,'⚡🌩️','轰隆隆！打雷啦！小水滴们抱在一起，变得越来越重。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,5,'🏔️💧','水滴变成雨落下来，流进了小河，又流到了大海洋里。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (84,6,'🏫😊','神奇校车带我们回家啦！原来水是这样旅行的，科学真太有趣了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,1,'👧🌸','第一次走进花园，哇，有好多漂亮的花，它们都叫什么名字呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,2,'🦋🌻','第一次看到蝴蝶从蛹里钻出来，它的翅膀好美丽，像会飞的花朵！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,3,'🌧️🌈','第一次在雨后看到彩虹，七种颜色挂在天边，好神奇呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,4,'🌙⭐','第一次用望远镜看月亮，上面有好多坑坑洼洼，月亮上真的没有小兔子吗？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,5,'🍂🌱','第一次看到树叶从绿变黄再落下来，原来秋天是这样来的呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (85,6,'🌍😊','世界上还有好多好多第一次等着我们呢，一起去发现吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,1,'👨‍🔬🌿','法布尔爷爷最喜欢观察小虫子了，他蹲在草地上看了好久好久。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,2,'🪲🏠','屎壳郎在推粪球，小小的身体推着大大的球，真努力呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,3,'🦗🎶','蟋蟀用翅膀摩擦发出好听的声音，就像在开一场小小的音乐会。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,4,'🐜💪','蚂蚁们排着长队搬运食物，一只搬不动就大家一起抬，真团结！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,5,'🦋🔄','毛毛虫慢慢地吐丝结茧，过了一些日子，竟然变成了美丽的蝴蝶！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (86,6,'🌿❤️','每一只小虫子都有自己了不起的本领，大自然真是太奇妙了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,1,'🐔🌊','卡梅拉是一只不一样的小鸡，她不想每天只会下蛋，她想去看看大海！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,2,'🚶‍♀️🌙','夜晚，卡梅拉偷偷离开了鸡舍，踏上了去海边的路。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,3,'🌊😮','终于看到大海了！蓝色的海水一望无际，卡梅拉开心地在海里游泳！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,4,'🚢🏝️','卡梅拉被海浪冲上了一艘大船，船上的人们都惊讶地看着她。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,5,'🐓💕','在新大陆，卡梅拉认识了皮迪克，他们一起回到了鸡舍。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (87,6,'🐣😊','卡梅拉有了自己的小宝宝，她要告诉他，外面的世界好大好精彩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,1,'📖🌍','打开这本百科全书，就像打开了一扇通往世界的大门！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,2,'🌋🏔️','地球上有高高的山峰，还有会喷火的火山，大自然的力量真伟大！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,3,'🦁🐘','非洲的大草原上，狮子和大象自由自在地生活着。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,4,'🚀🪐','宇宙里有好多好多的星球，我们住的地球只是其中一颗呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,5,'🦖🦴','很久很久以前，地球上住着巨大的恐龙，它们留下的化石告诉我们过去的故事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (88,6,'🧑‍🔬🔍','世界这么大，有好多奥秘等着我们去探索，你也来当小小科学家吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,1,'🌳👦','从前有一棵大树，她好爱好爱一个小男孩，小男孩也每天来找大树玩。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,2,'🍎🌿','男孩在树枝上荡秋千，吃树上甜甜的苹果，大树觉得好幸福。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,3,'💰😔','男孩长大了，需要钱，大树让他把自己的苹果拿去卖。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,4,'🏠🪵','男孩需要房子，大树让他砍下自己的树枝去盖房子。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,5,'🚢🪓','男孩想去远方，大树让他砍掉自己的树干做一条船。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (89,6,'🪵😌','男孩老了回来了，大树只剩下一个老树墩，她说：坐在我身上休息吧。爱就是这样的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,1,'🏘️😔','村子里的人们互不理睬，谁也不愿意分享自己的食物。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,2,'🧙‍♂️🍲','三个士兵来了，他们说要用石头煮一锅世界上最好喝的汤！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,3,'🪨💧','士兵们把石头放进大锅里加水煮，可是汤看起来还不够好喝呀。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,4,'🥕🧅','有人说：要是加点胡萝卜就好了。有人说：再加点洋葱吧。大家纷纷拿出了食材。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,5,'🍖🎉','你一点我一点，石头汤变得又香又浓，整个村子都闻到了香味！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (90,6,'🎊❤️','大家一起喝着美味的汤，跳着舞唱着歌。原来分享让一切都变得更美好！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,1,'🐱💀','有一只虎斑猫，它活了100万次，也死了100万次，可是它谁也不在乎。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,2,'👑😢','它曾经是国王的猫、水手的猫、小偷的猫，每次死后主人都会哭，但猫从来不哭。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,3,'🐈‍⬛😒','猫觉得活着真没意思，反正还会再活一次，它什么都不在乎。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,4,'😻💕','这一次，猫成了一只野猫，它遇见了一只美丽的白猫，它第一次心动了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,5,'👨‍👩‍👧‍👦🏠','猫和白猫生活在一起，有了可爱的小猫咪，它终于觉得活着是这么幸福。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (91,6,'😭❤️','白猫老了，慢慢地不动了，猫第一次哭了，它哭了100万次，再也不想活了。原来爱让生命有了意义。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,1,'⭕😄','有一个圆，它缺了一角，所以滚得不够快，它决定去找失落的那一角。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,2,'🌸🎵','一边滚一边找，它有时间和蝴蝶说话，还能闻闻花香，唱唱歌。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,3,'🔺❌','找到一个角，可是太大了！又找到一个，太小了！再找到一个，太尖了！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,4,'🧩✅','终于找到了完美匹配的那一角！圆现在滚得好快好快！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,5,'💨😢','滚得太快了，来不及和蝴蝶打招呼，也闻不到花香了，连歌都唱不了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (92,6,'⭕🌸','圆轻轻地放下了那一角，慢慢地继续滚着。有时候，不完美才是最快乐的呢！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,1,'👧🌸','花婆婆小时候答应爷爷，长大后要做一件让世界变得更美丽的事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,2,'🌍📚','花婆婆去了好多地方，在图书馆工作，在热带岛上生活，可是还没做到那件事。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,3,'🤧🌱','她生病了，在床上休息的时候，看到窗外鲁冰花开得好漂亮，心情好了起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,4,'🌺🏔️','病好以后，她撒了好多好多花种子，山坡上、小路边都开满了五颜六色的花。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,5,'🏘️🌈','整个小镇变成了花的海洋，人们走过都会开心地笑起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (93,6,'👧🌷','花婆婆终于做到了让世界变得更美丽的事！小朋友们，你们也可以哦！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,1,'🦁📚','有一天，一只大狮子走进了图书馆，他走路很轻很轻，一点声音都没有。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,2,'🤫📖','狮子学会了图书馆的规矩：要安静，不能大吼。他最喜欢听故事时间。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,3,'😊🧹','狮子成了图书馆的好帮手，用尾巴扫地，用大身子当书架，小朋友们都很喜欢他。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,4,'💥🚨','有一天，麦小姐摔倒了！狮子只好违反规矩，大声吼叫求救！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,5,'😢🚪','狮子觉得自己违反了规矩，难过的离开了图书馆，大家都很想他。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (94,6,'🦁❤️','原来在紧急的时候可以打破规矩！狮子回来了，图书馆又充满了快乐的笑声。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,1,'👦🌊','勇气有很多种。第一次骑自行车不用辅助轮，也是勇气。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,2,'🕯️😨','晚上关灯睡觉，虽然有点害怕，但还是闭上了眼睛，这就是勇气。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,3,'🍦🍎','忍住不吃第二块蛋糕，选择吃一个苹果，这也是一种勇气。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,4,'🤝😊','主动和新的小朋友打招呼说你好，是勇气的表现。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,5,'🙅‍♂️💪','别人都在做不对的事情时，勇敢地说不，这需要很大的勇气。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (95,6,'❤️🌟','不管勇气是大是小，每一次勇敢都让你变得更了不起！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,1,'🐷😊','小猪觉得做猪太无聊了，他决定要变成别的动物！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,2,'🦓🎨','小猪在身上画了条纹，假装自己是斑马，可是大象说：你不是斑马！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,3,'🐘🎭','小猪又假装自己是大象，在鼻子上绑了长管子，可是袋鼠一眼就看穿了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,4,'🦘🎈','小猪在脚上绑了大弹簧学袋鼠跳，结果摔了一大跤，好疼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,5,'🐦🪶','小猪又想做小鸟，装上翅膀从树上跳下来，扑通一声掉进了泥塘！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (96,6,'🐷💦','小猪在泥塘里滚来滚去，哇，好舒服呀！原来做自己才是最快乐的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,1,'👦😅','凯是个小男孩，他做什么事情好像都做不好，总是出状况。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,2,'🧥❌','穿衣服扣子扣歪了，鞋子穿反了，凯觉得自己真是太笨了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,3,'🥤💧','打翻牛奶，摔坏杯子，妈妈总是叹气，凯好难过。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,4,'🐱💬','一只大灰猫对凯说：你也可以很棒的，再试一次吧！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,5,'👟✅','凯小心翼翼地穿好鞋子，这次没有穿反！他好开心！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (97,6,'🎨😊','凯一笔一笔画了一幅画，画得真不错！凯能行，我也能行！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,1,'👧🩰','贝琳达最爱跳芭蕾了，可是她的脚好大好大，像两条大船。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,2,'😰👠','评委们说：你的脚太大了，永远跳不好芭蕾！贝琳达好伤心。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,3,'🍽️😊','贝琳达不再跳舞了，她在餐厅工作。可是每当音乐响起，她的脚就忍不住跳起来。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,4,'🎵💃','老板发现了贝琳达的舞蹈，请她在餐厅里表演，客人们看得目瞪口呆！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,5,'🎭👏','贝琳达的舞蹈太精彩了，大脚丫让她跳得更高更美！观众们掌声雷动！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (98,6,'❤️🩰','贝琳达终于站上了大舞台，大脚丫跳起芭蕾来简直太棒了！做自己最闪亮！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,1,'👧🩰','贝琳达想去学芭蕾，可是她的脚太大了，同学们都笑话她。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,2,'😢👠','老师让她演小丑，不用跳芭蕾，贝琳达心里好难过好难过。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,3,'🧹🎵','贝琳达每天打扫舞蹈教室，偷偷看着别人跳舞，自己也在一旁悄悄地练。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,4,'👀💫','有一天，老师看到了贝琳达的练习，她的舞姿竟然那么优美！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,5,'🎭🌹','老师让贝琳达上台表演，大脚丫旋转起来像一朵盛开的花！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (99,6,'👏😊','贝琳达终于学会了芭蕾！只要坚持努力，梦想一定会实现的！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,1,'👧👠','芭蕾舞团要演灰姑娘，贝琳达好想演主角，可是她的脚穿不上玻璃鞋。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,2,'😈😤','坏心眼的竞争对手故意换了小鞋子，说只有穿得进玻璃鞋的人才能演灰姑娘。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,3,'😢🎭','贝琳达穿不上玻璃鞋，只能演灰姑娘的姐姐，她伤心极了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,4,'⏰💥','演出那天，穿玻璃鞋的女孩扭伤了脚！贝琳达勇敢地站了出来！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,5,'💃✨','贝琳达用自己的方式跳起了灰姑娘，大脚丫跳出的舞步比谁都精彩！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (100,6,'👑❤️','不需要玻璃鞋，贝琳达就是最美的灰姑娘！真正的公主不需要完美！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,1,'🐟🌊','大海里住着一群小红鱼和一条小黑鱼，他们每天都快乐地一起游泳。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,2,'😱🐋','有一天，一条大金枪鱼一口把小红鱼们都吞掉了，只剩下小黑鱼一个。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,3,'😿🌊','小黑鱼好孤单好害怕，它独自在深海里游来游去。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,4,'🪸🐙','一路上，小黑鱼看到了水母像果冻、海鳗像彩虹，大海真美丽！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,5,'🐟💪','小黑鱼找到了躲在礁石后面的小红鱼们，它说：我们一起游，组成一条大鱼！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (101,6,'🐟👁️😊','小黑鱼当了眼睛，大家一起游成一条最大的鱼，把大鱼都吓跑了！团结就是力量！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,1,'🐌🍎','小蜗牛对爸爸说：我想要世界上最大的房子！爸爸讲了一个故事给他听。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,2,'🏗️✨','从前有一只小蜗牛，他拼命让自己的壳长大，长啊长，变得好大好大！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,3,'🌹🎀','大壳上长出了美丽的花纹，像一座华丽的城堡，大家都夸好看。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,4,'🥀😩','可是壳太大了，小蜗牛爬不动了，果子熟了吃不到，蝴蝶飞来也追不上。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,5,'💥😢','大壳太重了，蜗牛只好缩在里面，什么风景也看不到了。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (102,6,'🐌🍃','小蜗牛听了故事，决定只要一个小小的壳就好。小小的壳才能看到大大的世界呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,1,'🧩❓','佩泽提诺是一块小小的橘色方块，他觉得别人都是完整的，只有自己是碎的。');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,2,'🏃‍♂️❓','他问跑得飞快的：我是你掉下来的一小块吗？不是呀，我跑这么快怎么会少一块！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,3,'💪❓','他又去问大力士：我是你掉下来的吗？大力士笑了：我这么强壮，怎么会少！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,4,'⛵❓','他去问智者和帆船，每个人都很完整，佩泽提诺到底是从哪里来的呢？');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,5,'💥😮','砰！佩泽提诺摔了一跤，碎成了好多更小的方块！原来自己也是完整的呀！');
INSERT INTO book_page (book_id, page_num, illustration, text) VALUES (103,6,'🧩😊','佩泽提诺开心地把自己拼回去，他不再觉得自己是别人掉下来的了，我就是我！');